insert into public.curated_course_resources (course_id, kind, title, link_or_site, description, sort_order)
values
  ('2d02aee6-f186-43f1-be42-8d31d01e8725', 'textbook'::public.curated_course_resource_kind, 'Lehninger Principles of Biochemistry', 'Macmillan', 'Nelson and Cox. Comprehensive shared reference for structure, enzymology, metabolism, bioenergetics, regulation, and molecular biology.', 0),
  ('2d02aee6-f186-43f1-be42-8d31d01e8725', 'textbook'::public.curated_course_resource_kind, 'Biochemistry (Berg, Tymoczko, Gatto, and Stryer)', 'Macmillan', 'Strong conceptual narrative, molecular mechanism, protein function, and pathway logic. Used by MIT 7.05.', 1),
  ('2d02aee6-f186-43f1-be42-8d31d01e8725', 'textbook'::public.curated_course_resource_kind, 'Biochemistry (Miesfeld and McEvoy)', 'W. W. Norton', 'Readable mechanistic treatment and contemporary examples. An MIT-listed alternative.', 2),
  ('2d02aee6-f186-43f1-be42-8d31d01e8725', 'textbook'::public.curated_course_resource_kind, 'Biochemistry (Voet and Voet)', 'Wiley', 'Deeper chemistry, physical basis, enzymology, and metabolic detail for Chemistry students and instructor enrichment.', 3),
  ('2d02aee6-f186-43f1-be42-8d31d01e8725', 'textbook'::public.curated_course_resource_kind, 'Biochemistry Free For All', 'https://open.oregonstate.education/biochemistryfreeforall/', 'Oregon State University. Free course-length reference, figures, and review support.', 4),
  ('2d02aee6-f186-43f1-be42-8d31d01e8725', 'website'::public.curated_course_resource_kind, 'MIT OCW 7.05 General Biochemistry', 'https://ocw.mit.edu/courses/7-05-general-biochemistry-spring-2020/', 'Undergraduate lectures, problem sets, exams, and a metabolism-centered second half.', 5),
  ('2d02aee6-f186-43f1-be42-8d31d01e8725', 'website'::public.curated_course_resource_kind, 'MIT OCW 5.07SC Biological Chemistry I', 'https://ocw.mit.edu/courses/5-07sc-biological-chemistry-i-fall-2013/', 'Chemistry-forward explanations of recurring reaction types, bioenergetics, and pathway mechanisms.', 6),
  ('2d02aee6-f186-43f1-be42-8d31d01e8725', 'website'::public.curated_course_resource_kind, 'ASBMB core concepts and exam goals', 'https://www.asbmb.org/education/exam/certification-exam-goals-and-objectives', 'Outcome map for energy/metabolism, structure/function, information transfer, scientific skills, homeostasis, and evolution.', 7),
  ('2d02aee6-f186-43f1-be42-8d31d01e8725', 'website'::public.curated_course_resource_kind, 'RCSB Protein Data Bank and PDB-101', 'https://www.rcsb.org/', 'Macromolecular structures, molecular visualization, structure-function cases, and accessible teaching materials. Also https://pdb101.rcsb.org/.', 8),
  ('2d02aee6-f186-43f1-be42-8d31d01e8725', 'website'::public.curated_course_resource_kind, 'UniProt', 'https://www.uniprot.org/', 'Curated sequence, function, localization, variants, cofactors, and cross-references.', 9),
  ('2d02aee6-f186-43f1-be42-8d31d01e8725', 'website'::public.curated_course_resource_kind, 'BRENDA', 'https://www.brenda-enzymes.org/', 'Enzyme reactions, kinetic parameters, organisms, substrates, inhibitors, and literature links.', 10),
  ('2d02aee6-f186-43f1-be42-8d31d01e8725', 'website'::public.curated_course_resource_kind, 'KEGG and Reactome', 'https://www.genome.jp/kegg/pathway.html', 'Pathway context, molecular participants, disease links, and comparative network exploration. Also https://reactome.org/.', 11),
  ('2d02aee6-f186-43f1-be42-8d31d01e8725', 'website'::public.curated_course_resource_kind, 'PubChem', 'https://pubchem.ncbi.nlm.nih.gov/', 'Structures, properties, identifiers, bioassays, and safety/context for metabolites, cofactors, and inhibitors.', 12),
  ('2d02aee6-f186-43f1-be42-8d31d01e8725', 'website'::public.curated_course_resource_kind, 'NCBI Bookshelf', 'https://www.ncbi.nlm.nih.gov/books/', 'Free authoritative books and chapters for molecular biology, metabolism, nutrition, genetics, and disease.', 13),
  ('2d02aee6-f186-43f1-be42-8d31d01e8725', 'website'::public.curated_course_resource_kind, 'iBiology and HHMI BioInteractive', 'https://www.ibiology.org/', 'Research-facing lectures, animations, case materials, and connections between biochemical concepts and discovery. Also https://www.biointeractive.org/.', 14),
  ('2d02aee6-f186-43f1-be42-8d31d01e8725', 'website'::public.curated_course_resource_kind, 'Python: Jupyter, NumPy, SciPy, pandas, Matplotlib', 'https://jupyter.org/', 'Reproducible curve fitting, pathway accounting, data visualization, uncertainty analysis, and report-ready notebooks. Also https://scipy.org/.', 15);
